import{describe,it,expect}from"vitest";import{districts,divisions,regions,getDistrictById,getDistrictsByDivision,getDistrictsByRegion,filterDistricts}from"../../frontend/up-district-explorer/up-district-explorer.js";const REQUIRED_DISTRICT_FIELDS=["id","name","division","region","headquarters","population","attractions","industries","cuisine","festivals","coords"];describe("UP District Explorer Dataset Completeness & Integrity",()=>{it("contains exactly all 75 districts of Uttar Pradesh",()=>{expect(districts.length).toBe(75)}),it("contains all 18 administrative divisions of Uttar Pradesh",()=>{expect(divisions.length).toBe(18);const t=new Set(districts.map(t=>t.division));divisions.forEach(e=>{expect(t.has(e),`Division ${e} has no districts`).toBe(!0)})}),it("contains all 4 geographic regions of Uttar Pradesh",()=>{expect(regions.length).toBe(4);const t=new Set(districts.map(t=>t.region));regions.forEach(e=>{expect(t.has(e),`Region ${e} has no districts`).toBe(!0)})}),it("every district profile contains all required fields with valid types",()=>{districts.forEach((t,e)=>{REQUIRED_DISTRICT_FIELDS.forEach(i=>{expect(t,`District at index ${e} missing field ${i}`).toHaveProperty(i),["attractions","industries","cuisine","festivals"].includes(i)?(expect(Array.isArray(t[i])).toBe(!0),expect(t[i].length).toBeGreaterThan(0)):"coords"===i?(expect(typeof t.coords.x).toBe("number"),expect(typeof t.coords.y).toBe("number")):(expect(typeof t[i]).toBe("string"),expect(t[i].trim().length).toBeGreaterThan(0))})})}),it("all district IDs and names are unique across all 75 items",()=>{const t=districts.map(t=>t.id),e=districts.map(t=>t.name);expect(new Set(t).size).toBe(75),expect(new Set(e).size).toBe(75)})}),describe("District Query Helpers",()=>{it("retrieves district profile by ID or name",()=>{const t=getDistrictById("varanasi");expect(t).toBeDefined(),expect(t.name).toBe("Varanasi"),expect(t.headquarters).toBe("Varanasi");const e=getDistrictById("Taj Mahal");expect(e).toBeUndefined();const i=getDistrictById("Lucknow");expect(i).toBeDefined(),expect(i.id).toBe("lucknow")}),it("retrieves all districts in a specific division (e.g. Agra Division)",()=>{const t=getDistrictsByDivision("Agra");expect(t.length).toBe(4);const e=t.map(t=>t.id);expect(e).toContain("agra"),expect(e).toContain("mathura")}),it("retrieves all districts in a specific region (e.g. Bundelkhand)",()=>{const t=getDistrictsByRegion("Bundelkhand");expect(t.length).toBeGreaterThanOrEqual(7)})}),describe("Search & Filter Helpers",()=>{it("filters districts by search query (e.g. Petha or Taj Mahal)",()=>{const t=filterDistricts("Petha");expect(t.length).toBeGreaterThan(0),expect(t[0].id).toBe("agra")}),it("filters districts by division and region combined",()=>{const t=filterDistricts("","Lucknow","Awadh");expect(t.length).toBe(6)}),it("returns empty array when search query matches nothing",()=>{const t=filterDistricts("NonExistentPlaceXYZ");expect(t).toEqual([])})});